CREATE ROLE authenticated; CREATE ROLE anon; CREATE ROLE service_role;
CREATE SCHEMA auth; CREATE SCHEMA platform_private; CREATE SCHEMA storage;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('test.actor',true),'')::uuid $$;
CREATE FUNCTION public.is_platform_superadmin(uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT $1='00000000-0000-4000-8000-000000000001'::uuid $$;
CREATE FUNCTION platform_private.catalog_metadata_require_actor() RETURNS uuid LANGUAGE plpgsql AS $$ BEGIN IF NOT coalesce(public.is_platform_superadmin(auth.uid()),false) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; RETURN auth.uid(); END $$;
CREATE FUNCTION platform_private.require_service_role() RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF current_setting('test.service',true) IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; END $$;
CREATE FUNCTION public.fn_regulatory_can_read() RETURNS boolean LANGUAGE sql AS $$ SELECT true $$;
CREATE FUNCTION platform_private.catalog_tenant_actor(text) RETURNS uuid LANGUAGE sql AS $$ SELECT '00000000-0000-4000-8000-000000000010'::uuid $$;
CREATE TABLE public.organizations(id uuid PRIMARY KEY,nome text,ativo boolean,status text);
CREATE TABLE public.produtos(id uuid PRIMARY KEY,nome text,codigo text,ativo boolean,e_insumo boolean,owner_organization_id uuid);
CREATE TABLE public.microrganismos(id uuid PRIMARY KEY,nome text,codigo text,product_id uuid,owner_organization_id uuid);
CREATE TABLE public.formulacoes(produto_id uuid,microrganismo_id uuid,owner_organization_id uuid);
CREATE TABLE public.microorganism_regulatory_dossiers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),microorganism_id uuid,version int,status text,deleted_at timestamptz,updated_at timestamptz DEFAULT clock_timestamp(),created_by uuid,updated_by uuid,strain_code text,strain_name text,regulatory_category text,formulation text,label_guarantee text,guarantee_unit text,mapa_registration_number text,mapa_holder text,mapa_manufacturer text,mapa_status text,mapa_valid_until date,mapa_not_applicable_reason text,notes text,technical_review_status text DEFAULT 'PENDING',regulatory_review_status text DEFAULT 'PENDING',fiscal_review_status text DEFAULT 'PENDING');
CREATE UNIQUE INDEX mrd_uq_open_per_micro ON public.microorganism_regulatory_dossiers(microorganism_id) WHERE status IN ('DRAFT','PENDING_REVIEW') AND deleted_at IS NULL;
CREATE UNIQUE INDEX mrd_uq_published_per_micro ON public.microorganism_regulatory_dossiers(microorganism_id) WHERE status='VALIDATED' AND deleted_at IS NULL;
CREATE TABLE public.product_regulatory_dossier_links(product_id uuid PRIMARY KEY,dossier_id uuid UNIQUE);
CREATE TABLE public.microorganism_regulatory_documents(id uuid PRIMARY KEY,dossier_id uuid,doc_type text,title text,storage_bucket text DEFAULT 'fiscal-regulatorio',storage_path text,content_sha256 text,issuer text,issued_at date,valid_until date,uploaded_by uuid,deleted_at timestamptz);
CREATE UNIQUE INDEX doc_hash ON public.microorganism_regulatory_documents(dossier_id,content_sha256);
CREATE TABLE public.microorganism_regulatory_checklist(dossier_id uuid,item_key text,state text,justification text,decided_by uuid,decided_at timestamptz,PRIMARY KEY(dossier_id,item_key));
CREATE TABLE storage.objects(bucket_id text,name text);
CREATE TABLE public.company_fiscal_settings(organization_id uuid,crt text);
CREATE FUNCTION public.fn_regulatory_storage_path_ok(text) RETURNS boolean LANGUAGE sql AS $$ SELECT $1 LIKE 'dossiers/%' $$;
CREATE FUNCTION public.fn_microorganism_regulatory_facts(p_microorganism_id uuid) RETURNS jsonb LANGUAGE sql AS $$ SELECT to_jsonb(d) FROM public.microorganism_regulatory_dossiers d WHERE microorganism_id = p_microorganism_id AND deleted_at IS NULL LIMIT 1 $$;
CREATE FUNCTION public.rpc_regulatory_dossier_detail(p_microorganism_id uuid) RETURNS jsonb LANGUAGE sql AS $$ SELECT to_jsonb(d) FROM public.microorganism_regulatory_dossiers d WHERE microorganism_id = p_microorganism_id AND deleted_at IS NULL LIMIT 1 $$;
CREATE FUNCTION platform_private.rpc_regulatory_dossier_ensure_draft__tenant_core(p_microorganism_id uuid) RETURNS uuid LANGUAGE sql AS $$ SELECT id FROM public.microorganism_regulatory_dossiers WHERE microorganism_id = p_microorganism_id LIMIT 1 $$;
CREATE FUNCTION platform_private.rpc_regulatory_product_dossier_detail(uuid,uuid) RETURNS jsonb LANGUAGE sql AS $$ SELECT '{}'::jsonb $$;
CREATE FUNCTION public.touch_dossier() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at:=clock_timestamp(); RETURN NEW; END $$;
CREATE TRIGGER touch BEFORE UPDATE ON public.microorganism_regulatory_dossiers FOR EACH ROW EXECUTE FUNCTION public.touch_dossier();
